					match = true;
					break;
				}
				if (!match) for (String bn : BASE_COPYABLE_ANNOTATIONS) if (typeMatches(bn, node, annotationTypeName)) {
					result.append(annotation);
					break;
				}
			}
		}
		return result.toList();
	}

